-- =====================================================================
-- 5. SELECT COM JOIN
-- =====================================================================

-- J01 - Quais processos ativos existem, de qual cliente e quem é o advogado responsável?
SELECT p.id_processo, c.nome AS cliente, p.tipo, p.prazo, e.nome AS responsavel
FROM Processo p
JOIN Cliente c ON c.id_cliente = p.id_cliente
JOIN Processo_Equipe pe ON pe.id_processo = p.id_processo AND pe.papel = 'Responsavel'
JOIN Equipe e ON e.id_advogado = pe.id_advogado
WHERE p.status = 'Ativo'
ORDER BY p.prazo
LIMIT 15;

-- J02 - Quais devedores pertencem a cada carteira?
SELECT ca.nome AS carteira, d.nome AS devedor, d.situacao_divida
FROM Devedor d
JOIN Carteira ca ON ca.id_carteira = d.id_carteira
ORDER BY ca.nome, d.nome
LIMIT 20;

-- J03 - Quais são as negociações com o devedor e o valor já pago em cada uma?
SELECT n.id_negociacao, d.nome AS devedor, n.tipo, n.status, n.valor_total,
       SUM(pg.valor_pago) AS total_pago
FROM Negociacao n
JOIN Devedor d ON d.id_devedor = n.id_devedor
JOIN Pagamento pg ON pg.id_negociacao = n.id_negociacao
GROUP BY n.id_negociacao, d.nome, n.tipo, n.status, n.valor_total
ORDER BY n.id_negociacao
LIMIT 20;

-- =====================================================================
-- 6. UPDATE
-- =====================================================================

-- U01 - Prorrogar o prazo de um processo.
UPDATE Processo
SET prazo = '2026-11-25'
WHERE id_processo = 151;

-- U02 - Atualizar o telefone de um cliente.
UPDATE Cliente
SET telefone = '(11) 90000-0019'
WHERE id_cliente = 19;

-- U03 - Arquivar um processo que já foi encerrado.
UPDATE Processo
SET status = 'Arquivado'
WHERE id_processo = 5 AND status = 'Encerrado';

-- =====================================================================
-- 7. DELETE
-- Primeiro cadastramos um devedor duplicado (por engano) e depois apagamos.
-- Apaga primeiro o contato (tabela filha) e depois o devedor.
-- =====================================================================

INSERT INTO Devedor (id_carteira, nome, cpf_cnpj, situacao_divida)
VALUES (1, 'Devedor Duplicado', '000.999.999-99', 'Ativa');

INSERT INTO Contato (id_devedor, meio, data, resultado)
SELECT id_devedor, 'Telefone', '2026-11-05 09:00:00', 'Sem resposta'
FROM Devedor
WHERE cpf_cnpj = '000.999.999-99';

-- D01 - Apagar o contato do devedor duplicado.
DELETE FROM Contato
WHERE id_devedor IN (SELECT id_devedor FROM Devedor WHERE cpf_cnpj = '000.999.999-99');

-- D02 - Apagar o devedor duplicado.
DELETE FROM Devedor
WHERE cpf_cnpj = '000.999.999-99';

-- =====================================================================
-- 8. CONSULTAS GERENCIAIS
-- KPI01 = valor recuperado por carteira (soma dos pagamentos das negociações)
-- KPI02 = arrecadação por mês (soma de todos os pagamentos recebidos)
-- =====================================================================

-- G01 - Quantos devedores, negociações e quanto foi recebido em cada carteira?
-- Atende: P1 (informações espalhadas) e KPI01
SELECT ca.nome AS carteira,
       COUNT(DISTINCT d.id_devedor) AS devedores,
       COUNT(DISTINCT n.id_negociacao) AS negociacoes,
       SUM(pg.valor_pago) AS valor_recebido
FROM Carteira ca
JOIN Devedor d ON d.id_carteira = ca.id_carteira
LEFT JOIN Negociacao n ON n.id_devedor = d.id_devedor
LEFT JOIN Pagamento pg ON pg.id_negociacao = n.id_negociacao
GROUP BY ca.id_carteira, ca.nome
ORDER BY ca.nome;

-- G02 - Quais processos em andamento vencem nos próximos 30 dias (a partir de 05/11/2026)?
-- Atende: P2 (dificuldade de acompanhar prazos e situação dos processos)
SELECT p.id_processo, c.nome AS cliente, p.tipo, p.status, p.prazo, e.nome AS responsavel
FROM Processo p
JOIN Cliente c ON c.id_cliente = p.id_cliente
JOIN Processo_Equipe pe ON pe.id_processo = p.id_processo AND pe.papel = 'Responsavel'
JOIN Equipe e ON e.id_advogado = pe.id_advogado
WHERE p.status IN ('Ativo', 'Suspenso')
  AND p.prazo BETWEEN '2026-11-05' AND '2026-12-05'
ORDER BY p.prazo;

-- G03 - Quanto foi arrecadado em cada mês?
-- Atende: KPI02 (arrecadação por período)
SELECT DATE_FORMAT(data_pagamento, '%Y-%m') AS mes,
       COUNT(*) AS qtd_pagamentos,
       SUM(valor_pago) AS total_arrecadado
FROM Pagamento
GROUP BY DATE_FORMAT(data_pagamento, '%Y-%m')
ORDER BY mes;

-- =====================================================================
-- 9. CONSULTAS DE AUDITORIA
-- Cada consulta mostra as linhas que quebram a regra. Se não aparece nada, a regra está ok.
-- =====================================================================

-- A01 - Existe negociação sem responsável?
-- Verifica: RN15 (toda atividade tem um responsável)
SELECT n.id_negociacao, n.status, n.valor_total
FROM Negociacao n
WHERE n.id_responsavel IS NULL;

-- A02 - Existe pagamento registrado em negociação cancelada?
-- Verifica: RN04 (pagamento só com acordo formalizado)
SELECT pg.id_pagamento, pg.data_pagamento, pg.valor_pago, n.id_negociacao, n.status
FROM Pagamento pg
JOIN Negociacao n ON n.id_negociacao = pg.id_negociacao
WHERE n.status = 'Cancelada'
ORDER BY pg.data_pagamento;

-- A03 - Existe processo com honorários pagos mas sem contrato de honorários?
-- Verifica: RN09 (honorários ligados a um processo com origem identificada)
SELECT p.id_processo, p.tipo, p.status
FROM Processo p
WHERE p.id_processo IN (SELECT id_processo FROM Pagamento WHERE id_processo IS NOT NULL)
  AND p.id_processo NOT IN (SELECT id_processo FROM Documento WHERE tipo = 'Contrato de Honorarios')
ORDER BY p.id_processo;